import sys


def main():
    data = sys.stdin.read().split()
    n, k = int(data[0]), int(data[1])
    pts = set()
    for i in range(n):
        pts.add((int(data[2 + 2 * i]), int(data[3 + 2 * i])))
    cnt = 0
    for x, y in pts:
        if (x + k, y) in pts and (x, y + k) in pts and (x + k, y + k) in pts:
            cnt += 1
    print(cnt)


